import { isArraysEqualDeeply } from "./isArraysEqualDeeply";
import { isArraysEqualShallow } from "./isArraysEqualShallow";
import { isBothArraysShallow } from "./isBothArraysShallow";
import { isElementsEqual } from "./isElementsEqual";
import { isObject } from "./isObject";
import { isObjectsEqualShallow } from "./isObjectsEqualShallow";
import { isPrimitive } from "./isPrimitive";
const isBothArrays = (elem1, elem2) => Array.isArray(elem1) && Array.isArray(elem2);
const isArraysNotEqual = (val1, val2) => {
    if (!isBothArrays(val1, val2)) {
        return false;
    }
    if (isBothArraysShallow(val1, val2) && !isArraysEqualShallow(val1, val2)) {
        return true;
    }
    if (!isArraysEqualDeeply(val1, val2)) {
        return true;
    }
    return false;
};
const isBothObjectsShallow = (val1, val2) => isObject(val1) && isObject(val2);
const isPrimitivesNotEqual = (item1, item2) => isPrimitive(item1) && isPrimitive(item2) && item1 !== item2;
const isObjectsNotEqualShallow = (val1, val2) => {
    if (!isObject(val1) || !isObject(val2)) {
        return false;
    }
    if (isBothObjectsShallow(val1, val2) && !isObjectsEqualShallow(val1, val2)) {
        return true;
    }
    return false;
};
export const isPropertiesEqual = (elem1, elem2) => {
    const elem1Keys = Object.keys(elem1);
    for (const key of elem1Keys) {
        if (isPrimitivesNotEqual(elem1[key], elem2[key])) {
            return false;
        }
        if (isArraysNotEqual(elem1[key], elem2[key])) {
            return false;
        }
        if (isObjectsNotEqualShallow(elem1[key], elem2[key])) {
            return false;
        }
        if (!isElementsEqual(elem1[key], elem2[key])) {
            return false;
        }
    }
    return true;
};
